# -*- coding: utf-8 -*-
"""
KVKK Korumalı Şifreli İsim Listesi Verisi.
Bu dosya GitHub'a yüklendiğinde içerikteki kişisel veriler okunamaz.
"""
import base64
import json
import pandas as pd
import streamlit as st

_ENCRYPTED_DATA = ""

def get_decrypted_df(key_str="MTH_KVKK_SECRET_2026"):
    try:
        # Streamlit secrets'tan şifre alma seçeneği
        if hasattr(st, "secrets") and "PERSONEL_KEY" in st.secrets:
            key_str = st.secrets["PERSONEL_KEY"]
            
        key_bytes = key_str.encode('utf-8')
        encrypted_bytes = base64.b64decode(_ENCRYPTED_DATA.encode('utf-8'))
        decrypted_bytes = bytearray()
        for i, b in enumerate(encrypted_bytes):
            decrypted_bytes.append(b ^ key_bytes[i % len(key_bytes)])
        
        json_str = decrypted_bytes.decode('utf-8')
        data_list = json.loads(json_str)
        df = pd.DataFrame(data_list)
        if "PERSONEL KODU" in df.columns:
            df["PERSONEL KODU"] = df["PERSONEL KODU"].astype(str).str.strip()
        return df
    except Exception as e:
        return None
